<?php defined('BASEPATH') OR exit('No direct script access allowed');
class Workspace extends MY_Controller {
 private $c; public function __construct(){parent::__construct();$this->c=$this->require_auth();if(!$this->c){$this->output->_display();exit;}$this->load->model('Workspace_model','workspaces');}
 public function dashboard(){list($org,$ws)=$this->workspaces->context($this->c['sub'],$this->c['organizationId']);list($tasks,$total)=$this->workspaces->tasks($org['id'],8);$active=0;$done=0;foreach($tasks as &$t){if($t['status']==='IN_PROGRESS')$active++;if($t['status']==='DONE')$done++;$t=$this->task_view($t);}return $this->respond(array('organization'=>array_intersect_key($org,array_flip(array('id','name','slug'))),'workspace'=>$ws?array_intersect_key($ws,array_flip(array('id','name','slug'))):NULL,'stats'=>array('agentsTotal'=>0,'agentsOnline'=>0,'tasksActive'=>$active,'tasksPending'=>max(0,$total-$active-$done),'tasksDone'=>$done),'agents'=>array(),'tasks'=>$tasks,'activities'=>$this->workspaces->activities($org['id'])));}
 public function tasks(){$oid=$this->c['organizationId'];if($this->input->method(TRUE)==='POST'){$d=$this->body();if(empty(trim($d['title']??''))||strlen($d['title'])>200)return $this->fail('VALIDATION_ERROR','Task title is required',422);if(isset($d['priority'])&&!in_array($d['priority'],array('LOW','MEDIUM','HIGH','URGENT'),TRUE))return $this->fail('VALIDATION_ERROR','Invalid priority',422);list(,$ws)=$this->workspaces->context($this->c['sub'],$oid);return $this->respond($this->task_view($this->workspaces->create_task($oid,$ws['id']??NULL,$this->c['sub'],$d)),201);}$page=max(1,(int)$this->input->get('page'));$per=min(100,max(1,(int)($this->input->get('perPage')?:20)));list($rows,$total)=$this->workspaces->tasks($oid,$per,($page-1)*$per,$this->input->get('status'),$this->input->get('q'));return $this->respond(array('items'=>array_map(array($this,'task_view'),$rows),'pagination'=>array('page'=>$page,'perPage'=>$per,'total'=>$total,'totalPages'=>(int)ceil($total/$per))));}
 public function task($id){$d=$this->body();if(isset($d['status'])&&!in_array($d['status'],array('TODO','IN_PROGRESS','BLOCKED','DONE','CANCELLED'),TRUE))return $this->fail('VALIDATION_ERROR','Invalid status',422);if(isset($d['progress'])&&((int)$d['progress']<0||(int)$d['progress']>100))return $this->fail('VALIDATION_ERROR','Invalid progress',422);list(,$ws)=$this->workspaces->context($this->c['sub'],$this->c['organizationId']);$r=$this->workspaces->update_task($id,$this->c['organizationId'],$this->c['sub'],$ws['id']??NULL,$d);return $r?$this->respond($this->task_view($r)):$this->fail('NOT_FOUND','Task not found',404);}
 public function task_view($t){return array('id'=>$t['id'],'title'=>$t['title'],'description'=>$t['description'],'status'=>$t['status'],'priority'=>$t['priority'],'progress'=>(int)$t['progress'],'dueDate'=>$t['due_date'],'createdAt'=>$t['created_at'],'agent'=>NULL,'assignee'=>NULL,'creator'=>array('id'=>$t['creator_id'],'email'=>$this->c['email'],'displayName'=>NULL));}
}
